  const isAvailable = confidence !== null && confidence !== undefined;
  const safeConfidence = isAvailable ? confidence : 0;
  const springValue = useSpring(0, { stiffness: 60, damping: 15 });
  const [displayValue, setDisplayValue] = useState(0);

